from taf.ul.ettf.events.notifier import Notifier
from taf.ul.ettf.events.comparator import On
from taf.ul.ettf.events.event import Teardown
from taf.ul.ettf.events.lifetime_policy import OneTimeCall
from taf.ul.ettf.events.registration_condition import UniqueCallback
from taf.ul.ettf.msg_capture.comparison_registry import ComparisonRegistry
from taf.ul.ettf.msg_capture.condition_wrappers.msg_collector import MsgCollector
from taf.ul.ettf.msg_capture.condition_wrappers.utils import setup_registry
from taf.ul.ettf.typed.typed import typed
from taf.ul.ettf.logger import custom_logger
from taf.ul.ettf.msg_capture.interface import scoped_logger, assert_variable_conversion_type
from taf.ul.ettf.msg_capture.filter_builder import FilterBuilder
from taf.ul.ettf.msg_capture.expectation_builders.detailed import MessageHeader, DetailedMessageBuilder
from taf.ul.ettf.msg_capture.expectation_builders.full import FullMessage, FullMessageBuilder
from taf.ul.ettf.msg_capture.storage import Storage
from taf.ul.ettf.msg_capture.condition_wrappers.ordered import Ordered as MatchWithOrder
from taf.ul.ettf.msg_capture.condition_wrappers.non_ordered import NonOrdered as MatchWithoutOrder
from taf.ul.ettf.state_machine import machinery
from taf.ul.ettf.pdml_parser import parse
from taf.ul.ettf.utils.exception import LibraryError
from taf.ul.ettf.utils import exception_causes
from taf.ul.ettf.utils.robot_handlers import with_callback_name
from future.utils import with_metaclass
import types
import inspect


logger = custom_logger('msg_capture.expectations')
notifier = Notifier()
TIMEOUT = 30


class ExpectedMessagesError(LibraryError):
    def __init__(self, msg):
        super(ExpectedMessagesError, self).__init__(exception_causes.DOES_NOT_EXIST, msg)


def get(argument_name, kwargs):
    value = kwargs.get(argument_name, None)
    if not value:
        raise ExpectedMessagesError('{} is expected! {} should be passed as an argument in decorated_method'.format(argument_name, argument_name))
    assert_variable_conversion_type(var_value=value, expected_type=int, var_name=argument_name)
    return value


def update_kwargs(func, kwargs):
    inspected_func = inspect.getargspec(func)

    if inspected_func.args is not None and inspected_func.defaults is not None:
        updated_kwargs = dict(zip(reversed(inspected_func.args), reversed(inspected_func.defaults)))
        updated_kwargs.update(kwargs)
        return updated_kwargs

    return kwargs


class ClearingGuard(object):
    def __init__(self, instance):
        self.instance = instance

    def __enter__(self, *args, **kwargs):
        self.instance.capturing_logger_started()
        return self

    def __exit__(self, *args, **kwargs):
        self.instance.clear()
        self.instance.capturing_logger_finished()


def expected_messages(wrapped_method):
    def func(procedure_class_instance, *args, **kwargs):
        updated_kwargs = update_kwargs(wrapped_method, kwargs)

        expectations = procedure_class_instance.build_expectations()
        run_counter = procedure_class_instance.run_counter

        if expectations and run_counter == RunCounter.NOT_RUNNING:
            condition_type = procedure_class_instance.matching_params.get_matching_order()
            timeout = procedure_class_instance.matching_params.get_timeout()
            filter_data = procedure_class_instance._provide_filtering_data(updated_kwargs)

            registry = ComparisonRegistry()
            collector = MsgCollector(*expectations)
            setup_registry(collector, registry)

            with scoped_logger(interface=filter_data.interfaces, pdml_parser=parse, msg_filter=filter_data.capturing_filter) \
                    as msg_capturer, ClearingGuard(procedure_class_instance):
                try:
                    with msg_capturer.capture_until(condition=collector, timeout=timeout) as captured_messages:
                        result = wrapped_method(procedure_class_instance, *args, **updated_kwargs)

                    condition = condition_type(*expectations)
                    setup_registry(condition, registry)
                    condition.verify(captured_messages)
                finally:
                    registry.show()
                return result

        else:
            return wrapped_method(procedure_class_instance, *args, **kwargs)
    return func


def is_decoratable(attr_object):
    return isinstance(attr_object, types.FunctionType) and \
        not isinstance(attr_object, staticmethod) and \
        not attr_object.__name__.startswith('_')


class Expectations(object):
    def __init__(self):
        self.expectations = []

    def append(self, expectation):
        self.expectations.append(expectation)

    def get(self):
        return self.expectations

    def get_unwrapped(self):
        return [e.matcher for e in self.expectations]

    def clear(self):
        self.expectations = []

    def teardown(self):
        self.clear()


class RunCounter(int):
    NOT_RUNNING = 0

    def __init__(self, *args, **kwargs):
        super(RunCounter, self).__init__(*args, **kwargs)
        self.clear()

    def clear(self):
        self = 0  # noqa

    @with_callback_name('Msg Capture Run Counter Teardown')
    def teardown(self):
        self.clear()


class MatchingParams(object):
    def __init__(self, timeout, matching_order):
        self.initial_timeout = timeout
        self.timeout = timeout
        self.initial_matching_order = matching_order
        self.matching_order = matching_order

    def get_timeout(self):
        return self.timeout

    def get_matching_order(self):
        return self.matching_order

    @typed(timeout=float)
    def change_timeout(self, timeout):
        self.timeout = timeout

    def change_matching_order(self, matching_order):
        self.matching_order = matching_order

    def clear(self):
        self.timeout = self.initial_timeout
        self.matching_order = self.initial_matching_order


class WithExpectationsMeta(type):
    def __new__(cls, name, bases, local):

        for attr in local:
            attr_object = local[attr]

            if is_decoratable(attr_object):
                local[attr] = expected_messages(attr_object)

        return type.__new__(cls, name, bases, local)


gexpectations = Expectations()
gstorage = Storage()
grun_counter = RunCounter()
gmatching_params = MatchingParams(TIMEOUT, MatchWithOrder)
INITIAL_STATE_EVENTS = {
    FullMessage: lambda: FullMessageBuilder(gexpectations, gstorage),
    MessageHeader: lambda: DetailedMessageBuilder(gexpectations, gstorage),
}
gexpectations_creator = machinery.Machinery(transition_map=INITIAL_STATE_EVENTS)


class ExpectationsManagerBase(object):
    def __init__(self):
        super(ExpectationsManagerBase, self).__init__()

        self.expectations_creator = gexpectations_creator
        self.expectations = gexpectations
        self.storage = gstorage
        self.run_counter = grun_counter
        self.matching_params = gmatching_params

        notifier.register(self.run_counter.teardown, On(Teardown), OneTimeCall(), UniqueCallback())
        notifier.register(self.storage.teardown, On(Teardown), OneTimeCall(), UniqueCallback())
        notifier.register(self.clear, On(Teardown), OneTimeCall(), UniqueCallback())

    @with_callback_name('Expectations Manager Clear', append_class_name=True)
    def clear(self):
        self.expectations_creator.finish()
        self.expectations.clear()
        self.matching_params.clear()

    def capturing_logger_started(self):
        self.run_counter += 1

    def capturing_logger_finished(self):
        self.run_counter -= 1

    def build_expectations(self):
        self.expectations_creator.finish()
        return self.expectations.get()

    def _provide_filtering_data(self, wrapped_method_args):
        raise Exception('Not implemented!')


class ExpectationsManager(ExpectationsManagerBase):
    def append_expectation(self, expectation_event):
        self.expectations_creator.process(expectation_event)

    def store(self, key, matcher, storage_policy):
        self.storage.store(key, matcher, storage_policy)

    def get_stored(self, key):
        return self.storage.get(key)

    def is_stored(self, key):
        return self.storage.contains(key)

    @typed(timeout=float)
    def matching_timeout(self, timeout):
        self.matching_params.change_timeout(timeout)
        logger.debug('Timeout set to: {} seconds'.format(timeout))

    def match_with_order(self):
        self._set_matching_order(MatchWithOrder)

    def match_with_any_order(self):
        self._set_matching_order(MatchWithoutOrder)

    def _set_matching_order(self, matching_order):
        self.matching_params.change_matching_order(matching_order)
        logger.debug('Matching order set to: {}'.format(matching_order))


class WithUeSpecificExpectations(with_metaclass(WithExpectationsMeta, ExpectationsManagerBase)):
    def _provide_filtering_data(self, wrapped_method_args):
        ue_id = get('ue_id', wrapped_method_args)
        return FilterBuilder() \
            .with_rrc_ue_messages(ue_id) \
            .with_s1_messages() \
            .with_x2_messages() \
            .build()


class WithCellSpecificExpectations(with_metaclass(WithExpectationsMeta, ExpectationsManagerBase)):
    def _provide_filtering_data(self, wrapped_method_args):
        cell_id = get('cell_id', wrapped_method_args)
        return FilterBuilder() \
            .with_rrc_cell_messages(cell_id) \
            .with_s1_messages() \
            .with_x2_messages() \
            .build()
